<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {useRoute} from 'vue-router'
import {mcpApi,projectsApi,type McpBinding} from '../api'
import {errorMessage} from '../utils'
const pid=Number(useRoute().params.projectId),name=ref(''),bindings=ref<McpBinding[]>([]),busy=ref(false),error=ref(''),message=ref('')
async function load(){busy.value=true;error.value='';try{const[p,b]=await Promise.all([projectsApi.get(pid),mcpApi.bindings(pid)]);name.value=p.name;bindings.value=b;for(const item of b)item.tools=Object.fromEntries(item.server.tools.map(tool=>[tool.name,item.valid&&item.tools[tool.name]?item.tools[tool.name]:{enabled:false,mode:'unknown'}]))}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function save(item:McpBinding){busy.value=true;error.value='';message.value='';try{await mcpApi.bind(pid,item);message.value='本项目工具授权已保存，新提问生效；进行中的旧调用将停止。';await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><main class="page-content"><div class="page-header"><div><h1>{{name}} · MCP 工具授权</h1><p>只开放本项目所需工具。服务注解不会自动授权，只读分类由你审核。</p></div><router-link to="/settings/mcp">管理 MCP 服务 →</router-link></div><el-alert title="外部数据权限由服务账号决定，项目绑定仅限制可调用的工具。请使用受限账号或独立服务控制数据范围；写入和未知工具每次调用均需确认。" type="warning" :closable="false"/><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="message" :title="message" type="success" :closable="false"/><el-button :loading="busy" @click="load">刷新授权</el-button><el-empty v-if="!bindings.length&&!busy" description="先到 MCP 服务页添加并发现工具"/><el-card v-for="item in bindings" :key="item.server.id" class="binding-card"><h3>{{item.server.name}} <el-tag>{{item.server.enabled?'服务启用':'服务禁用'}}</el-tag></h3><p v-if="!item.valid" class="field-help">尚未绑定或服务已更新，请重新选择工具并保存；旧授权不生效。</p><el-empty v-if="!item.server.tools.length" description="暂无目录，请先连接并发现工具"/><div v-for="tool in item.server.tools" :key="tool.name" class="grant"><el-checkbox v-model="item.tools[tool.name]!.enabled" :disabled="busy||!item.server.enabled">允许 {{tool.name}}</el-checkbox><el-select v-model="item.tools[tool.name]!.mode" :aria-label="`${tool.name} 权限分类`" :disabled="busy"><el-option label="未知（每次确认）" value="unknown"/><el-option label="写入（每次确认）" value="write"/><el-option label="我已审核：只读" value="readonly"/></el-select><p>{{tool.description}}</p><details><summary>输入参数与服务注解</summary><pre>{{JSON.stringify({schema:tool.inputSchema,annotations:tool.annotations},null,2)}}</pre></details></div><el-button type="primary" :disabled="busy||!item.server.tools.length" @click="save(item)">保存本项目授权</el-button></el-card><router-link :to="`/projects/${pid}/requirements?agent=1`">返回项目助手 →</router-link></main></template>
<style scoped>.binding-card{margin:18px 0}.grant{border-top:1px solid #e5eaf0;margin:16px 0;padding:12px 0}.grant .el-select{width:220px;margin-left:16px}.grant pre{white-space:pre-wrap;max-height:260px;overflow:auto}.page-content>.el-alert{margin-bottom:16px}</style>
